changeSet.sql:
ALTER TABLE estoque_movimentacao DROP CONSTRAINT ck_estoque_movimentacao_tipo;
ALTER TABLE estoque_movimentacao ADD CONSTRAINT ck_estoque_movimentacao_tipo
    CHECK (tipo IN ('ENTRADA', 'AJUSTE', 'TRANSFERENCIA_SAIDA', 'TRANSFERENCIA_ENTRADA',
                    'SAIDA_CONSULTA'));

ALTER TABLE estoque_movimentacao DROP CONSTRAINT ck_estoque_movimentacao_sinal;
ALTER TABLE estoque_movimentacao ADD CONSTRAINT ck_estoque_movimentacao_sinal
    CHECK (quantidade <> 0
           AND (tipo NOT IN ('ENTRADA', 'TRANSFERENCIA_ENTRADA') OR quantidade > 0)
           AND (tipo NOT IN ('TRANSFERENCIA_SAIDA', 'SAIDA_CONSULTA') OR quantidade < 0));

ALTER TABLE estoque_movimentacao ADD CONSTRAINT ck_estoque_movimentacao_consulta
    CHECK ((tipo = 'SAIDA_CONSULTA') = (consulta_id IS NOT NULL));

